if(!isset($a,$cmbAction,$e,$input)||empty($a['account_uuid']))return;
$slots=[];foreach($cmb['speed_dials']??[] as $row)if($row['account_uuid']===$a['account_uuid'])$slots[(int)$row['slot']]=$row;
